def is_square_int(n):
    if n < 0:
        return False, None
    # integer sqrt via Newton's method / binary search
    x = int(n**0.5)
    # adjust around floating error
    while (x+1)*(x+1) <= n:
        x += 1
    while x*x > n:
        x -= 1
    return x*x == n, x

def verifier(assign):
