    for k in ('a_side','b_side','ab_len_num','ab_len_den'):
        if k not in assign:
            # missing slot
            return (False, None)
    a = assign['a_side']
    b = assign['b_side']
    num = assign['ab_len_num']
    den = assign['ab_len_den']
    # Basic checks
    if not (isinstance(a, int) and isinstance(b, int) and isinstance(num, int) and isinstance(den, int)):
        return (False, None)
    if a <= 0 or b <= 0 or den <= 0 or num <= 0:
        return (False, None)
    L = Fraction(num, den)
    # Enforce non-trivial: unequal sides and valid AB segment length
    if a == b:
        return (False, None)  # harder-than-seed: unequal sides only
    if not (L > 0 and L < a):
        return (False, None)
    # Reconstruct K from the quadratic: L*K^2 - b*K + (a - L) = 0.
    # Discriminant Δ = b^2 - 4 L (a - L). For octagon regime generated by our method, Δ is a rational perfect square.
    Delta = Fraction(b*b, 1) - 4*L*(Fraction(a, 1) - L)
    # Check Delta is nonnegative rational and a perfect square of a rational
    # For a rational q = n/d, sqrt(q) rational iff n and d are perfect squares.
    n = Delta.numerator
    d = Delta.denominator
    ok_n, rn = is_square_int(n)
    ok_d, rd = is_square_int(d)
    if not (ok_n and ok_d):
        return (False, None)
    sqrtDelta = Fraction(rn, rd)
    # K must be the larger root: K = (b + sqrtDelta)/(2 L)
    K = (Fraction(b, 1) + sqrtDelta) / (2*L)
    # Octagon regime: K > max(a/b, b/a)
    from fractions import Fraction as F
    if not (K > F(max(a, b), min(a, b))):
        return (False, None)
    # Compute area using exact formula: A = a^2 - (a*K - b)^2 / (K^2 - 1)
    AK_minus_b = Fraction(a, 1)*K - Fraction(b, 1)
    denom = K*K - 1
    if denom <= 0:
        return (False, None)
    A = Fraction(a*a, 1) - (AK_minus_b*AK_minus_b)/denom
    # Reduce to lowest terms and return m+n
    m = A.numerator
    n = A.denominator
    # Additional difficulty checks: ensure octagon area is neither trivial nor reducible to 2L (which happens when a=b)
    if m <= 0 or n <= 0:
        return (False, None)
    # Everything ok
    return True, (m + n)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

